using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class VersionWorkshopCacheTests {
 static int checks,failed;static List<object> results=new List<object>();
 static void Check(bool ok,string label){checks++;if(!ok){failed++;Console.WriteLine("FAIL "+label);}}
 static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
 sealed class Captured {public string Hash;public long Write,Length;}
 static Dictionary<string,Captured> Capture(string source){var rows=new Dictionary<string,Captured>(StringComparer.OrdinalIgnoreCase);var pending=new Stack<string>();pending.Push(source);while(pending.Count>0)foreach(string path in SnapshotFileSystem.Directories.EnumerateFileSystemEntries(pending.Pop())){if((SnapshotFileSystem.Files.GetAttributes(path)&FileAttributes.Directory)!=0){pending.Push(path);continue;}var info=new SnapshotFileSystem.Info(path);string hash;using(var input=new SnapshotFileSystem.Stream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(input)).Replace("-","");rows.Add(path.Substring(source.Length+1).Replace('\\','/'),new Captured{Hash=hash,Write=info.LastWriteTimeUtc.Ticks,Length=info.Length});}return rows;}
 static bool Same(Dictionary<string,Captured> before,Dictionary<string,Captured> after){return before.Count==after.Count&&before.All(pair=>after.ContainsKey(pair.Key)&&pair.Value.Hash==after[pair.Key].Hash&&pair.Value.Write==after[pair.Key].Write&&pair.Value.Length==after[pair.Key].Length);}
 static void Run(string root,bool update){string folder=Path.Combine(root,update?"缓存可独立更新":"缓存不属于游戏版本"),game=Path.Combine(folder,"原游戏"),target=Path.Combine(folder,"独立版本"),data=Path.Combine(folder,"启动器数据"),user=Path.Combine(folder,"玩家目录");
  var payload=new Dictionary<string,string>{{"ProjectZomboid64.exe","owned; never execute"},{"ProjectZomboid64.json","{\"vmArgs\":[]}"},{"version.txt","42.21.0"},{"media/中文资源.bin",new string('g',1048576)},{"Workshop/ModTemplate/Contents/mods/Template/42/mod.info","id=Template\n"},{"mods/Keep/42/mod.info","id=Keep\n"},{"OrangeLauncherRuntime/custom/component.bin","owned installed component"},{"steamapps/workshop-tools/tool.txt","similarly named legitimate neighbor"},{"$runtime/unknown.txt","unknown historical directory is retained"},{"Saves/unknown.txt","unverified directory is retained"}};
  foreach(var pair in payload)Put(Path.Combine(game,pair.Key),pair.Value);string cache=Path.Combine(game,"sTeAmApPs","WoRkShOp","content","108600","1234567890","mods","Cached","42","cache.bin");Put(cache,new string('c',2097152));Directory.CreateDirectory(Path.Combine(game,"steamapps","workshop","empty-cache"));var before=Capture(game);long expected=payload.Keys.Sum(path=>new FileInfo(Path.Combine(game,path)).Length);var events=new List<VersionCopyProgress>();var library=new VersionLibrary(data,game,user);bool changed=false,completed=false;string error=null;
  try{library.Preserve(game,target,"缓存边界测试",CancellationToken.None,p=>{events.Add(p);if(update&&!changed&&p.Stage=="copy"&&p.BytesCopied>0){changed=true;Put(cache,"owned cache updated independently");Put(Path.Combine(game,"STEAMAPPS","WORKSHOP","new-item","new.bin"),"new owned cache item");}});completed=true;}catch(IOException failure){error=failure.ToString();}
  Check(completed,(update?"workshop update cannot invalidate body copy":"body copy completes")+": "+error);var after=Capture(game);if(!update)Check(Same(before,after),"all source files and mtimes unchanged");else{Check(changed,"actual source cache was updated during copy");Check(payload.Keys.All(path=>before[path].Hash==after[path].Hash&&before[path].Write==after[path].Write),"game payload source hashes and mtimes unchanged");}
  if(completed){var copied=Capture(target);Check(copied.Count==payload.Count,"exact body file count without cache");Check(payload.Keys.All(path=>copied.ContainsKey(path)&&copied[path].Hash==before[path].Hash&&copied[path].Write==before[path].Write),"templates mods components and unverified directories retained exactly");Check(!Directory.Exists(Path.Combine(target,"steamapps","workshop")),"no nested workshop cache directory copied");Check(events.Where(p=>p.Stage=="copy"||p.Stage=="verifyCopy").All(p=>p.TotalBytes==expected&&p.TotalFiles==payload.Count),"copy and verification totals exclude cache");Check(events.Where(p=>p.Stage=="scan"||p.Stage=="verifySource").All(p=>p.File==null||!p.File.Replace('\\','/').StartsWith("steamapps/workshop/",StringComparison.OrdinalIgnoreCase)),"scan and source recheck do not hash workshop payload");Check(library.List().Count==2,"one independent version registered");}
  Check(!Directory.GetDirectories(folder,"*.partial-*").Any(),"no partial directory remains");results.Add(new{UpdateDuringCopy=update,Completed=completed,Error=error,BodyFiles=payload.Count,BodyBytes=expected,Before=before,After=after,Target=target});
 }
 static void LongPaths(string root){string folder=Path.Combine(root,"中文长路径"),game=Path.Combine(folder,"原游戏"),data=Path.Combine(folder,"数据"),user=Path.Combine(folder,"用户"),target=Path.Combine(folder,"独立版本"),cancelTarget=Path.Combine(folder,"取消再重试");
  Put(Path.Combine(game,"ProjectZomboid64.exe"),"owned; never execute");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");string relative="media/"+string.Join("/",Enumerable.Range(0,9).Select(i=>"中文路径超过传统长度限制的真实文件夹"+i))+"/中文内容.bin";string deep=Path.Combine(game,relative);SnapshotFileSystem.Directories.CreateDirectory(Path.GetDirectoryName(deep));SnapshotFileSystem.Files.WriteAllBytes(deep,Enumerable.Range(0,3*1048576+97).Select(i=>(byte)(i%251)).ToArray());
  var before=Capture(game);Check(deep.Length>260&&Path.Combine(target+".partial-"+new string('a',32),relative).Length>260,"fixture uses real Chinese paths longer than 260 characters");var library=new VersionLibrary(data,game,user);bool complete=false;string error=null;try{library.Preserve(game,target,"真实长中文路径",CancellationToken.None);complete=true;}catch(Exception failure){error=failure.ToString();}Check(complete,"real long-path normal copy completes: "+error);if(complete){Check(Same(before,Capture(target)),"long-path output matches all content hashes lengths and mtimes");Check(library.List().Count==2,"long-path version is registered");}
  bool canceled=false,issued=false;string cancelError=null;using(var cts=new CancellationTokenSource()){try{library.Preserve(game,cancelTarget,"长路径取消",cts.Token,p=>{if(p.Stage=="copy"&&p.File==relative&&p.BytesCopied>1048576){issued=true;cts.Cancel();}});}catch(OperationCanceledException){canceled=true;}catch(Exception failure){cancelError=failure.ToString();}}
  Check(issued&&canceled,"cancel during actual long-path payload copy: "+cancelError);Check(!SnapshotFileSystem.Directories.Exists(cancelTarget),"canceled long-path target is absent");Check(!SnapshotFileSystem.Directories.EnumerateFileSystemEntries(folder).Any(path=>Path.GetFileName(path).Contains(".partial-")),"long-path cancellation deletes all owned staging directories");bool retry=false;string retryError=null;try{library.Preserve(game,cancelTarget,"长路径重试",CancellationToken.None);retry=true;}catch(Exception failure){retryError=failure.ToString();}Check(retry,"same long-path target retry succeeds: "+retryError);if(retry)Check(Same(before,Capture(cancelTarget)),"long-path retry content and mtimes match");Check(Same(before,Capture(game)),"long-path source files and mtimes remain unchanged");results.Add(new{LongPath=true,SourceFileCharacters=deep.Length,StagingFileCharacters=Path.Combine(target+".partial-"+new string('a',32),relative).Length,Completed=complete,Error=error,CancelIssued=issued,Canceled=canceled,CancelError=cancelError,Retry=retry,RetryError=retryError,SourceUnchanged=Same(before,Capture(game)),Target=target});
 }
 public static int Main(string[] args){LauncherRuntime.Initialize();try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Run(root,false);Run(root,true);LongPaths(root);File.WriteAllText(Path.Combine(root,"workshop-boundary-results.json"),new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{Checks=checks,Failed=failed,Results=results,Scope="Production Preserve with real owned recursive workshop files and real cache update, no game/UI"}),new UTF8Encoding(false));Console.WriteLine((failed==0?"PASS":"FAIL")+" "+checks+" checks; "+failed+" failed");return failed==0?0:1;}catch(Exception e){Console.WriteLine(e);return 2;}}
}}
